"""Task-local inspection: list workspace files and inspect any SQLite DBs."""
import os
import sqlite3


def main() -> None:
    print("=== Files in workspace ===")
    for entry in sorted(os.listdir(".")):
        print(entry)

    print("\n=== SQLite databases ===")
    for entry in sorted(os.listdir(".")):
        if entry.endswith(".db"):
            print(f"\n--- {entry} ---")
            conn = sqlite3.connect(entry)
            try:
                tables = conn.execute(
                    "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
                ).fetchall()
                for (table,) in tables:
                    cols = conn.execute(f"PRAGMA table_info({table})").fetchall()
                    print(f"table: {table}")
                    for col in cols:
                        print(f"  {col[1]} {col[2]}")
            finally:
                conn.close()


if __name__ == "__main__":
    main()

